import numpy as np
from typing import List

class SearchArray:
    def __init__(self, array: List[str]):
        self.array = array

    def phrase_freq(self, tokens: List[str], slop=1) -> np.ndarray:
        """
        This function calculates the frequency of a phrase within a SearchArray instance based on the provided tokens and slop.

        If the slop is 1 and all tokens are unique, it attempts to directly calculate the phrase frequencies using the positions of terms.
        If the slop is not 1 or tokens are not unique, it delegates the calculation to another method that handles different slops or non-unique tokens.

        Input-Output Arguments
        :param self: SearchArray. An instance of the SearchArray class.
        :param tokens: List[str]. A list of tokens (words) for which the phrase frequency is to be calculated.
        :param slop: int, optional. The maximum distance between tokens in the phrase. Defaults to 1, meaning tokens must be adjacent.
        :return: np.ndarray. An array of phrase frequencies corresponding to the tokens in the SearchArray instance.
        """

        # Check if all tokens are unique
        if len(tokens) == len(set(tokens)):
            # If slop is 1, calculate phrase frequencies directly
            if slop == 1:
                # Initialize frequency array
                freq = np.zeros(len(self.array))

                # Iterate over the array to find phrases
                for i in range(len(self.array) - len(tokens) + 1):
                    # Check if the phrase matches
                    if self.array[i:i+len(tokens)] == tokens:
                        # Increment frequency
                        freq[i] = 1

                # Return frequency array
                return freq
            else:
                # Delegate calculation to another method for different slops
                return self._calculate_phrase_freq_with_slop(tokens, slop)
        else:
            # Delegate calculation to another method for non-unique tokens
            return self._calculate_phrase_freq_with_non_unique_tokens(tokens, slop)

    def _calculate_phrase_freq_with_slop(self, tokens: List[str], slop: int) -> np.ndarray:
        # Initialize frequency array
        freq = np.zeros(len(self.array))

        # Iterate over the array to find phrases
        for i in range(len(self.array) - len(tokens) + 1):
            # Check if the phrase matches with the given slop
            for j in range(len(tokens)):
                if self.array[i+j] != tokens[j]:
                    break
                if j == len(tokens) - 1:
                    # Increment frequency
                    freq[i] = 1

        # Return frequency array
        return freq

    def _calculate_phrase_freq_with_non_unique_tokens(self, tokens: List[str], slop: int) -> np.ndarray:
        # Initialize frequency array
        freq = np.zeros(len(self.array))

        # Iterate over the array to find phrases
        for i in range(len(self.array) - len(tokens) + 1):
            # Check if the phrase matches
            match = True
            for j in range(len(tokens)):
                if self.array[i+j] != tokens[j]:
                    match = False
                    break
            if match:
                # Increment frequency
                freq[i] = 1

        # Return frequency array
        return freq
